column3:
services: {
  auth: id(svc_auth) & {port:8080}
  billing: id(svc_billing) & {
    dependsOn: [&: refer(), svc_auth]
  }
}

services: {
  auth: id(svc_auth) & {kind:service, port:8080}
  billing: id(svc_billing) & {
    dependsOn: [&: refer({kind:service}), svc_auth]
  }
}

services: {
  auth: id(svc_auth) & {port:8080}
  billing: id(svc_billing) & {
    dependsOn: [&: refer(), svc_auth, svc_payments]
  }
}

a: id(x) & { to: [&: refer({k:1}), y] }
b: id(y) & { to: [&: refer({k:1}), z] }
c: id(z) & { to: [&: refer({k:1}), x] }
